#include <algorithm>
#include <execution>
#include <vector>

std::vector<int> evens(const std::vector<int>& v) {
  std::vector<int> out;
  std::for_each(std::execution::par, v.begin(), v.end(), [&](int x) {
    if (x % 2 == 0) out.push_back(x);
  });
  return out;
}

