#include <algorithm>
#include <execution>
#include <vector>

std::vector<int> visit() {
  std::vector<int> idx{0, 1, 2, 3};
  std::vector<int> order;
  std::for_each(std::execution::seq, idx.begin(), idx.end(),
                [&](int i) { order.push_back(i); });
  return order;
}

#include <algorithm>
#include <execution>
#include <mutex>
#include <vector>

int sum(const std::vector<int>& v) {
  std::mutex m;
  int total = 0;
  std::for_each(std::execution::par_unseq, v.begin(), v.end(), [&](int x) {
    std::lock_guard<std::mutex> lock(m);
    total += x;
  });
  return total;
}
